import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Google Drive Module","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/modules/gdrive.md","filePath":"en/deep-dive/modules/gdrive.md","lastUpdated":1787464281000}`),a={name:`deep-dive/modules/gdrive.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="google-drive-module" tabindex="-1">Google Drive Module <a class="header-anchor" href="#google-drive-module" aria-label="Permalink to “Google Drive Module”">​</a></h1><p>The Google Drive module registers the <code>gdrive</code> remote file system. It stores the vault in a Google Drive folder and performs file operations through the Google Drive public API. The module uses Google OAuth for authentication and does not use a third-party server or proxy.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h2><p>The module adds a <strong>Google Drive</strong> settings group. Configure these settings before selecting Google Drive as the remote file system:</p><h3 id="connect-account-account-connected" tabindex="-1">Connect account / Account connected <a class="header-anchor" href="#connect-account-account-connected" aria-label="Permalink to “Connect account / Account connected”">​</a></h3><p>This setting initiates the Google authorization process. Once authorized, the module stores the refresh token securely in Obsidian&#39;s secret storage and uses it to obtain short-lived access tokens as needed. The <strong>Disconnect</strong> option revokes the token with Google, removes it from secret storage, clears any cached access tokens, and deletes the stored account identifier.</p><h3 id="base-directory" tabindex="-1">Base directory <a class="header-anchor" href="#base-directory" aria-label="Permalink to “Base directory”">​</a></h3><p>This defines the folder in Google Drive that serves as the root directory for this vault. The value is normalized as a directory path. If left empty when the module starts, it defaults to <code>&lt;vault name&gt;/</code>. The specified folder is created automatically during the first synchronization.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The base directory is an application-managed namespace. The module can see and operate only on files that it created through its Google Drive integration. Files or folders created manually in Drive, or created by another application, are not visible to this module even when they are inside the configured base directory. They will not be imported, synchronized, or listed.</p><p>Do not manually create, rename, move, or maintain vault files in this Drive folder. Set the base directory in the module settings, then let the first sync create it and let Sync Engine manage its contents. Manual Drive operations can leave files outside the module&#39;s visible set or cause conflicting changes.</p><p>This is a consequence of Google&#39;s <code>drive.file</code> scope, not a filtering option that can be disabled in Sync Engine. The module is intentionally not granted full Drive access.</p></div><h3 id="delete-to-trash" tabindex="-1">Delete to trash <a class="header-anchor" href="#delete-to-trash" aria-label="Permalink to “Delete to trash”">​</a></h3><p>When enabled, files deleted remotely are moved to the Google Drive trash instead of being permanently removed. When disabled, deleted files are permanently erased immediately. Note that Google Drive typically clears items from the trash after 30 days.</p><h2 id="permissions-and-scopes" tabindex="-1">Permissions And Scopes <a class="header-anchor" href="#permissions-and-scopes" aria-label="Permalink to “Permissions And Scopes”">​</a></h2><p>The module requests exactly these OAuth scopes:</p><h3 id="drive-file" tabindex="-1"><code>drive.file</code> <a class="header-anchor" href="#drive-file" aria-label="Permalink to “drive.file”">​</a></h3><p>This scope permits the module to create and manage files that it creates in Google Drive. Sync requires this access to:</p><ul><li>Create the base directory and vault files</li><li>List the module&#39;s files so it can discover remote changes</li><li>Read file contents and metadata</li><li>Upload new contents and update existing files</li><li>Move or rename files</li><li>Delete files, either permanently or by moving them to trash</li></ul><p>The scope does <strong>not</strong> grant general access to the user&#39;s Drive. In particular, the module cannot discover or synchronize files created outside the plugin. Granting <code>drive.file</code> is a deliberate least-privilege choice: the module can manage its own sync data without receiving permission to read unrelated Drive files.</p><h3 id="openid" tabindex="-1"><code>openid</code> <a class="header-anchor" href="#openid" aria-label="Permalink to “openid”">​</a></h3><p>The <code>openid</code> scope makes Google return an OpenID Connect ID token during device authorization. The module reads the token&#39;s stable <code>sub</code> subject identifier and stores it as the connected account identifier. This lets Sync Engine identify which Google account is connected and distinguish multiple account connections, so that the sync record for different Google accounts don&#39;t interfere; it does not read the user&#39;s profile or request broad identity permissions.</p><h2 id="authentication-flow" tabindex="-1">Authentication Flow <a class="header-anchor" href="#authentication-flow" aria-label="Permalink to “Authentication Flow”">​</a></h2><p>The module uses <a href="https://developers.google.com/identity/protocols/oauth2/limited-input-device" target="_blank" rel="noreferrer"><strong>Google OAuth 2.0 for TV and Limited-Input Device Applications</strong></a>:</p><ol><li>When you click <strong>Connect</strong>, the module requests a device code from Google&#39;s device authorization endpoint with the two scopes above.</li><li>Obsidian displays Google&#39;s verification URL and a one-time user code. The module can copy the code and open the URL in a browser.</li><li>You sign in to Google in that browser and approve the requested access.</li><li>While the dialog remains open, Obsidian polls Google&#39;s token endpoint. It waits when authorization is pending and backs off when Google requests a slower polling interval.</li><li>After approval, Google returns a short-lived access token, a refresh token, and an OpenID ID token. The module extracts the account subject from the ID token, stores the refresh token in Obsidian&#39;s secret storage, and caches the access token in memory.</li><li>Later Drive requests use the cached access token. When it is close to expiry, the module exchanges the refresh token for a new access token. A failed request with HTTP 401 causes one forced refresh and retry.</li></ol><p>Device authorization is used because Obsidian mobile cannot reliably provide the local browser redirect, localhost listener, or desktop-style custom URL callback required by common interactive OAuth flows. Device authorization keeps the OAuth interaction in a normal browser while the Obsidian app polls Google&#39;s endpoint, so the same connection flow works on desktop and mobile.</p><h2 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h2><p>Last updated on <strong>August 23, 2026</strong>.</p><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h3><p>This Privacy Policy describes how the Sync Engine plugin for Obsidian with Google Drive module (“the Plugin”) handles your data when you connect a Google Drive account. The Plugin is open-source software licensed under the MIT License.</p><h3 id="data-we-collect" tabindex="-1">Data We Collect <a class="header-anchor" href="#data-we-collect" aria-label="Permalink to “Data We Collect”">​</a></h3><p><strong>We collect no data.</strong> The Plugin has no telemetry, no analytics, no remote logging service, and no backend server. No information about you, your files, or your usage ever leaves your local device.</p><h3 id="how-your-data-is-handled" tabindex="-1">How Your Data Is Handled <a class="header-anchor" href="#how-your-data-is-handled" aria-label="Permalink to “How Your Data Is Handled”">​</a></h3><p><strong>Google Account Connection</strong>:</p><p>When you click “Connect,” the Plugin initiates a Google Device Authorization flow directly between your device and Google’s servers. The Plugin requests only these scopes:</p><ul><li><code>drive.file</code>: Access to files created by the Plugin. Files created outside the Plugin are not visible to it, even inside the configured base directory.</li><li><code>openid</code>: Supplies a stable Google account subject identifier so the Plugin can identify and deduplicate connections</li></ul><p><strong>Token Storage</strong>:</p><p>OAuth refresh tokens are stored exclusively in Electron’s encrypted secret storage on your local device. Tokens are never transmitted to any third party, never logged, and never included in crash reports or diagnostics.</p><p><strong>File Operations</strong>:</p><p>All sync operations are triggered or scheduled manually by you. File reads and writes occur directly between your local Obsidian vault and Google Drive via Google’s API. No intermediary servers are involved.</p><p><strong>Data Retention</strong>:</p><p>Your data exists only on your local device and in your own Google Drive account. When you click “Disconnect,” the Plugin:</p><ol><li>Revokes the OAuth token with Google</li><li>Deletes all stored tokens from Electron secret storage</li></ol><p>After disconnection, no trace of your Google Account connection remains on your device.</p><h3 id="third-parties" tabindex="-1">Third Parties <a class="header-anchor" href="#third-parties" aria-label="Permalink to “Third Parties”">​</a></h3><p>The only third-party service involved is Google’s OAuth and Drive API, which you authorize directly. We have no relationship with Google beyond using their public APIs. We do not share, sell, or transfer any data to any entity.</p><h3 id="your-rights" tabindex="-1">Your Rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to “Your Rights”">​</a></h3><p>You have complete control:</p><ul><li>All data is on your local device; inspect it anytime</li><li>Click “Disconnect” to erase all local credentials instantly</li><li>Revoke access anytime at <code>https://myaccount.google.com/permissions</code></li><li>Your files remain in your Google Drive regardless of Plugin status</li></ul><h3 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to “Changes”">​</a></h3><p>Updates to this policy will be published in the Plugin’s GitHub repository and <code>https://sync.consensia.cc</code>. Continued use after changes constitutes acceptance.</p><h3 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h3><p>Open an issue on our GitHub repository for privacy-related questions.</p><h2 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to “Terms of Service”">​</a></h2><p>Last updated on <strong>August 23, 2026</strong>.</p><h3 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to “Acceptance”">​</a></h3><p>By installing or using the Sync Engine plugin for Obsidian with Google Drive module (“the Plugin”), you agree to these Terms. If you disagree, uninstall the Plugin immediately.</p><h3 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h3><p>The Plugin is provided under the MIT License. You may use, modify, and distribute it freely per that license’s terms.</p><h3 id="no-warranty" tabindex="-1">No Warranty <a class="header-anchor" href="#no-warranty" aria-label="Permalink to “No Warranty”">​</a></h3><p>THE PLUGIN IS PROVIDED “AS IS”, WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NONINFRINGEMENT. THE AUTHORS AND COPYRIGHT HOLDERS SHALL NOT BE LIABLE FOR ANY CLAIM, DAMAGES, OR OTHER LIABILITY ARISING FROM USE OF THE PLUGIN, INCLUDING DATA LOSS, SYNC FAILURES, OR GOOGLE DRIVE API CHANGES.</p><h3 id="user-responsibilities" tabindex="-1">User Responsibilities <a class="header-anchor" href="#user-responsibilities" aria-label="Permalink to “User Responsibilities”">​</a></h3><p>You are solely responsible for:</p><ul><li>Maintaining the security of your Google Account credentials</li><li>Understanding what data you choose to sync</li><li>Backing up important files independently of the Plugin</li><li>Complying with Google’s Terms of Service when connecting your Drive account</li><li>Ensuring your local device’s Electron secret storage remains secure</li></ul><h3 id="acceptable-use" tabindex="-1">Acceptable Use <a class="header-anchor" href="#acceptable-use" aria-label="Permalink to “Acceptable Use”">​</a></h3><p>Do not use the Plugin to:</p><ul><li>Violate Google’s API Terms of Service</li><li>Access accounts you do not own or lack authorization for</li><li>Circumvent Google Drive storage or rate limits</li><li>Distribute malware or illegal content via synced files</li></ul><h3 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to “Third-Party Services”">​</a></h3><p>The Plugin interacts with Google’s OAuth and Drive APIs. These services are governed by Google’s own Terms of Service and Privacy Policy. We have no control over Google’s services and accept no liability for their availability, changes, or termination.</p><h3 id="disconnection-termination" tabindex="-1">Disconnection &amp; Termination <a class="header-anchor" href="#disconnection-termination" aria-label="Permalink to “Disconnection &amp; Termination”">​</a></h3><p>You may terminate your use at any time by clicking “Disconnect” in the Plugin settings or uninstalling the Plugin. We reserve the right to discontinue development or distribution of the Plugin at any time without notice.</p><h3 id="limitation-of-liability" tabindex="-1">Limitation of Liability <a class="header-anchor" href="#limitation-of-liability" aria-label="Permalink to “Limitation of Liability”">​</a></h3><p>TO THE MAXIMUM EXTENT PERMITTED BY LAW, IN NO EVENT SHALL THE AUTHORS OR CONTRIBUTORS BE LIABLE FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES, INCLUDING LOST PROFITS, DATA LOSS, OR BUSINESS INTERRUPTION, REGARDLESS OF THEORY OF LIABILITY.</p><h3 id="governing-law" tabindex="-1">Governing Law <a class="header-anchor" href="#governing-law" aria-label="Permalink to “Governing Law”">​</a></h3><p>This Plugin is developed and maintained on a voluntary, non-commercial basis by contributors located in multiple jurisdictions worldwide. No single governing law applies.</p><p>These Terms shall be interpreted in accordance with general principles of international law and the MIT License under which the Plugin is distributed.</p><h3 id="changes-1" tabindex="-1">Changes <a class="header-anchor" href="#changes-1" aria-label="Permalink to “Changes”">​</a></h3><p>We may update these Terms at any time. Changes take effect upon publication in the GitHub repository. Continued use constitutes acceptance.</p><h3 id="contact-1" tabindex="-1">Contact <a class="header-anchor" href="#contact-1" aria-label="Permalink to “Contact”">​</a></h3><p>Open an issue on our GitHub repository for questions regarding these Terms.</p>`,77)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};